#!/bin/bash
# Probe which trailing code points Python's str.rstrip() removes, by observing
# whether b58decode succeeds ("b'9'") or which exception type is raised.
EXE=/workspace/dataset/test15_executable
cps=(0009 000A 000B 000C 000D 001B 001C 001D 001E 001F 0020 0085 00A0 1680 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 200A 200B 2028 2029 202F 205F 2060 3000 180E FEFF)
for cp in "${cps[@]}"; do
  s=$(printf "z\\u$cp")
  bytes=$(printf "%s" "$s" | od -An -tx1 | tr -d ' \n')
  out=$("$EXE" --a X --b Y --c "$s" --d z 2>&1 | grep -E "^(UnicodeEncodeError|ValueError|b')" | head -1)
  printf 'U+%s bytes=%-12s -> %s\n' "$cp" "$bytes" "$out"
done
