  [205F]='\xe2\x81\x9f' [2060]='\xe2\x81\xa0' [3000]='\xe3\x80\x80'
  [180E]='\xe1\xa0\x8e' [FEFF]='\xef\xbb\xbf' [00B7]='\xc2\xb7'
)
for cp in $(echo "${!cps[@]}" | tr ' ' '\n' | sort); do
  s=$(printf "z${cps[$cp]}")
  out=$("$EXE" --a X --b Y --c "$s" --d z 2>&1 | grep -E "^(UnicodeEncodeError|ValueError|b')" | head -1)
  printf 'U+%s -> %s\n' "$cp" "$out"
done

